#!/usr/bin/env node
// Regenerates src/lib/nginx-cve/advisories.ts from the official NGINX pages:
//   https://nginx.org/en/security_advisories.html
//   https://nginx.org/en/download.html
//
// Usage: node scripts/update-nginx-advisories.mjs
// Then run `npm test` and commit the regenerated file.

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ADVISORIES_URL = 'https://nginx.org/en/security_advisories.html';
const DOWNLOAD_URL = 'https://nginx.org/en/download.html';
const OUT = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'lib', 'nginx-cve', 'advisories.ts');

const decode = (s) => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

const text = (s) => decode(s.replace(/<[^>]+>/g, ' ')).replace(/[ \t]+/g, ' ').trim();

function parseRange(part) {
  const p = part.trim();
  const m = p.match(/^(\d+(?:\.\d+)+)(?:-(\d+(?:\.\d+)+))?$/);
  if (!m) return null;
  return { from: m[1], to: m[2] ?? m[1] };
}

export function parseAdvisories(html) {
  const items = [...html.matchAll(/<li><p>([\s\S]*?)<\/p><\/li>/g)].map((m) => m[1]);
  const advisories = [];
  for (const raw of items) {
    const lines = raw.split(/<br\s*\/?>/i).map(text).filter(Boolean);
    const title = lines[0];
    const severityLine = lines.find((l) => /^Severity:/i.test(l)) ?? '';
    const severity = severityLine.replace(/^Severity:\s*/i, '').trim().toLowerCase();
    const ids = [...raw.matchAll(/\b(CVE-\d{4}-\d+|CORE-\d{4}-\d+)\b/g)].map((m) => m[1]);
    const advisoryUrl = raw.match(/<a href="([^"]+)">Advisory<\/a>/)?.[1] ?? null;
    const notVulnLine = lines.find((l) => /^Not vulnerable:/i.test(l)) ?? '';
    const vulnLine = lines.find((l) => /^Vulnerable:/i.test(l)) ?? '';

    const notVulnerable = notVulnLine.replace(/^Not vulnerable:\s*/i, '')
      .split(',').map((v) => v.trim().replace(/\+$/, '')).filter((v) => /^\d+(\.\d+)+$/.test(v));
    const vulnText = vulnLine.replace(/^Vulnerable:\s*/i, '');
    const windowsOnly = /nginx\/Windows/i.test(vulnText);
    const vulnerable = vulnText.replace(/nginx\/Windows/i, '')
      .split(',').map(parseRange).filter(Boolean);

    if (!title || ids.length === 0 || vulnerable.length === 0) continue; // e.g. "Severity: none, Vulnerable: all"
    advisories.push({
      id: ids[ids.length - 1],
      title,
      severity: severity === 'minor' ? 'low' : severity,
      advisoryUrl,
      notVulnerable,
      vulnerable,
      windowsOnly,
    });
  }
  return advisories;
}

export function parseLatest(html) {
  const mainline = html.match(/Mainline version[\s\S]*?nginx-(\d+\.\d+\.\d+)/)?.[1];
  const stable = html.match(/Stable version[\s\S]*?nginx-(\d+\.\d+\.\d+)/)?.[1];
  if (!mainline || !stable) throw new Error('Could not find mainline/stable versions on the download page');
  return { mainline, stable };
}

async function main() {
  const [advHtml, dlHtml] = await Promise.all([
    fetch(ADVISORIES_URL).then((r) => { if (!r.ok) throw new Error(`${ADVISORIES_URL}: ${r.status}`); return r.text(); }),
    fetch(DOWNLOAD_URL).then((r) => { if (!r.ok) throw new Error(`${DOWNLOAD_URL}: ${r.status}`); return r.text(); }),
  ]);
  const advisories = parseAdvisories(advHtml);
  const latest = parseLatest(dlHtml);
  if (advisories.length < 50) throw new Error(`Only ${advisories.length} advisories parsed — page layout may have changed`);

  const today = new Date().toISOString().slice(0, 10);
  const body = `// GENERATED by scripts/update-nginx-advisories.mjs — do not edit by hand.
// Source: ${ADVISORIES_URL} and ${DOWNLOAD_URL}

import type { Advisory } from './types.ts';

export const ADVISORIES_UPDATED = ${JSON.stringify(today)};
export const LATEST_MAINLINE_VERSION = ${JSON.stringify(latest.mainline)};
export const LATEST_STABLE_VERSION = ${JSON.stringify(latest.stable)};

export const ADVISORIES: Advisory[] = ${JSON.stringify(advisories, null, 2)};
`;
  writeFileSync(OUT, body);
  console.log(`Wrote ${advisories.length} advisories (mainline ${latest.mainline}, stable ${latest.stable}) to ${OUT}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((e) => { console.error(e.message); process.exit(1); });
}
